#include <bits/stdc++.h>
using namespace std;

using ll = long long;
using pii = pair<int, int>;

template<typename T, typename U> inline T minimize(T& a, U b) { return b < a ? a = b, a : a; }
template<typename T, typename U> inline T maximize(T& a, U b) { return a < b ? a = b, a : a; }

#define FOR(i, a, b) for (int i = (a), _b = (b); i < _b; ++i)
#define REP(i, n) FOR(i, 0, n)

const int MAXN = 205, MAXM = MAXN * MAXN;
#define prev some

int readInt() { int x; cin >> x; return x; }

int prev_edge[MAXM], mark_node[MAXN], head_node[MAXN], from_edge[MAXM], cap_edge[MAXM], to_edge[MAXM], edge_count;
int gridA[MAXN][MAXN], gridB[MAXN][MAXN], red_cell[MAXN][MAXN], block_cell[MAXN][MAXN];
int dist_grid[MAXN][MAXN], temp_counter, dist_red[MAXN], visited_bfs[MAXN];
pair<int, int> bfs_queue[MAXN];
const int DX[4] = {0, -1, 0, 1};
const int DY[4] = {1, 0, -1, 0};

void insertEdge(int u, int v, int uv_cap, int vu_cap) {
	from_edge[edge_count] = u;
	to_edge[edge_count] = v;
	cap_edge[edge_count] = uv_cap;
	prev_edge[edge_count] = head_node[u];
	head_node[u] = edge_count++;
	from_edge[edge_count] = v;
	to_edge[edge_count] = u;
	cap_edge[edge_count] = vu_cap;
	prev_edge[edge_count] = head_node[v];
	head_node[v] = edge_count++;
}

int dfsFlow(int vertex, int sink, int flow_limit = 2000000000) {
	if (vertex == sink) return flow_limit;
	if (mark_node[vertex]++) return 0;
	for (int e = head_node[vertex]; ~e; e = prev_edge[e]) if (cap_edge[e]) {
		int neighbor = to_edge[e];
		int augment = dfsFlow(neighbor, sink, min(flow_limit, cap_edge[e]));
		if (augment) {
			cap_edge[e] -= augment;
			cap_edge[e ^ 1] += augment;
			return augment;
		}
	}
	return 0;
}

int computeMaxFlow(int source, int sink) {
	int total = 0;
	while (true) {
		memset(mark_node, 0, sizeof mark_node);
		int added = dfsFlow(source, sink);
		total += added;
		if (!added) break;
	}
	return total;
}

int main() {
	ios_base::sync_with_stdio(false); cin.tie(nullptr); cout.tie(nullptr);
	int n = readInt(), dt = readInt();
	memset(head_node, -1, sizeof head_node);
	memset(dist_grid, 63, sizeof dist_grid);
	REP(i, MAXN) dist_grid[i][i] = 0;
	REP(x, n) REP(y, n) {
		char c; cin >> c;
		if (c == 'Y') block_cell[x][y] = 1;
		else if (c == 'Z') red_cell[x][y] = 1;
		else gridA[x][y] = c - '0';
	}
	REP(x, n) REP(y, n) {
		char c; cin >> c;
		if (c != 'Y' && c != 'Z') {
			gridB[x][y] = c - '0';
			REP(d, 4) {
				int nx = x + DX[d], ny = y + DY[d];
				if (nx >= 0 && ny >= 0 && nx < n && ny < n && !block_cell[nx][ny] && !red_cell[nx][ny])
					dist_grid[x * n + y][nx * n + ny] = 1;
			}
		}
	}
	int total_nodes = n * n;
	REP(k, total_nodes) REP(i, total_nodes) REP(j, total_nodes)
		if (dist_grid[i][k] + dist_grid[k][j] < dist_grid[i][j])
			dist_grid[i][j] = dist_grid[i][k] + dist_grid[k][j];
	int front = 0, rear = 0;
	memset(dist_red, 63, sizeof dist_red);
	REP(i, n) REP(j, n)
		if (red_cell[i][j]) {
			bfs_queue[rear++] = {i, j};
			dist_red[i * n + j] = 0;
		}
	while (front != rear) {
		auto cur = bfs_queue[front++];
		int x = cur.first, y = cur.second;
		REP(d, 4) {
			int nx = x + DX[d], ny = y + DY[d];
			if (nx >= 0 && ny >= 0 && nx < n && ny < n && !block_cell[nx][ny] && !red_cell[nx][ny] && dist_red[nx * n + ny] > 1e9) {
				dist_red[nx * n + ny] = dist_red[x * n + y] + 1;
				bfs_queue[rear++] = {nx, ny};
			}
		}
	}
	int sink_node = MAXN - 1, source_node = MAXN - 2;
	REP(start_node, total_nodes) {
		memset(visited_bfs, 0, sizeof visited_bfs);
		front = 0; rear = 0;
		int sx = start_node / n, sy = start_node % n;
		if (block_cell[sx][sy] || red_cell[sx][sy]) continue;
		bfs_queue[rear++] = {sx, sy};
		visited_bfs[start_node] = 1;
		while (front != rear) {
			int x = bfs_queue[front].first, y = bfs_queue[front++].second;
			if (dist_grid[start_node][x * n + y] <= dt)
				insertEdge(start_node << 1, (x * n + y) << 1 | 1, 1000, 0);
			if (dist_grid[start_node][x * n + y] == dist_red[x * n + y]) continue;
			REP(d, 4) {
				int nx = x + DX[d], ny = y + DY[d], nid = nx * n + ny;
				if (nx >= 0 && ny >= 0 && nx < n && ny < n && !block_cell[nx][ny] && !red_cell[nx][ny] && dist_grid[start_node][nid] <= dist_red[nid] && dist_grid[start_node][nid] <= dt && dist_grid[start_node][nid] > dist_grid[start_node][x * n + y] && !visited_bfs[nid]) {
					bfs_queue[rear++] = {nx, ny};
					visited_bfs[nid] = 1;
				}
			}
		}
	}
	REP(i, total_nodes) insertEdge(source_node, i << 1, gridA[i / n][i % n], 0);
	REP(i, total_nodes) insertEdge((i << 1) | 1, sink_node, gridB[i / n][i % n], 0);
	cout << computeMaxFlow(source_node, sink_node);
}
